window.ANAT_Q=[{"q":1,"name":"Épine iliaque postéro-supérieure (EIPS)","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"os","group":"Os","pos":"Procubitus ou debout","how":"Sous les fossettes lombaires ; suivre la crête iliaque vers l’arrière jusqu’à la saillie.","chk":"À hauteur de S2 ; comparer les deux côtés.","old":["a-parcours-x0-2"],"ins":"**Grand fessier** (une partie de son origine) ; ligaments sacro-iliaques postérieurs et sacro-tubéral.","plates":[{"pl":"b-bassin","num":7}]},{"q":2,"name":"Crête iliaque","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"os","group":"Os","pos":"Debout ou en décubitus latéral","how":"Mains à plat sur les flancs, descendre jusqu’au bord osseux, puis suivre la crête d’avant en arrière.","chk":"Son sommet est à hauteur de L4–L5 : comparer droite et gauche (bassin horizontal ?).","old":["a-parcours-x0-0"],"ins":"**Obliques externe et interne**, **transverse** de l'abdomen, **grand dorsal**, **carré des lombes** ; en avant, le **TFL**.","plates":[{"pl":"r-parcours1","num":1},{"pl":"r-squelette","num":1},{"pl":"b-bassin","num":1}]},{"q":3,"name":"Épine iliaque antéro-supérieure (EIAS)","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"os","group":"Os","pos":"Décubitus dorsal","how":"Suivre la crête iliaque vers l’avant jusqu’à la saillie la plus antérieure, avec la pulpe du pouce.","chk":"Le sartorius et le TFL partent juste en dessous : ils se tendent en flexion de hanche.","old":["a-parcours-x0-1"],"ins":"**Sartorius** et **tenseur du fascia lata** ; le **ligament inguinal**.","plates":[{"pl":"r-squelette","num":2},{"pl":"b-bassin","num":3},{"pl":"b-coxal","num":2}]},{"q":4,"name":"Grand trochanter","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"os","group":"Os","pos":"Décubitus latéral ou dorsal","how":"Face latérale de la cuisse, une main sous la crête iliaque : paume à plat.","chk":"Il roule sous la main quand on tourne la hanche en dedans et en dehors.","old":["a-parcours-x0-4"],"ins":"**Moyen fessier** et **petit fessier**, **piriforme**, **obturateur interne et jumeaux** ; en dessous, origine du **vaste latéral**.","plates":[{"pl":"r-parcours1","num":5},{"pl":"r-squelette","num":4},{"pl":"b-femur","num":3}]},{"q":5,"name":"Moyen fessier","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Décubitus latéral, jambe du dessus tendue en abduction : entre la crête iliaque et le grand trochanter.","chk":"","o":"Face latérale (glutéale) de l’aile iliaque, sous la crête","t":"Face latérale du **grand trochanter**","nerf":"N. glutéal supérieur (L4–S1)","act":"**Abducteur principal** ; **stabilise le bassin en appui unipodal**. Fibres antérieures : RI · postérieures : RE.","old":["m-hanche-m2p","m-hanche-m2o","m-hanche-m2t","m-hanche-m2n","m-hanche-m2a"],"plates":[{"pl":"r-hanchemus","num":8},{"pl":"b-cuisse-post","num":2},{"pl":"b-fesse1","num":2}]},{"q":6,"name":"Grand fessier","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Procubitus, genou fléchi à 90° : soulever la cuisse de la table → la fesse durcit sous la main.","chk":"","o":"Face postérieure de l’ilium, sacrum, coccyx, ligament sacro-tubéral","t":"**Tubérosité glutéale** du fémur + tractus ilio-tibial","nerf":"N. glutéal inférieur (L5–S2)","act":"**Extension** de hanche (monter un escalier, se relever, courir) + **rotation externe**.","old":["m-hanche-m1p","m-hanche-m1o","m-hanche-m1t","m-hanche-m1n","m-hanche-m1a"],"plates":[{"pl":"r-hanchemus","num":9},{"pl":"b-coupe-cuisse","num":14},{"pl":"b-cuisse-int","num":10}]},{"q":8,"name":"Ischio-jambiers","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"Procubitus, genou légèrement fléchi.","how":"Flexion du genou contrariée : les tendons encadrent le **creux poplité**. En dehors, le **biceps fémoral** (vers la tête de la fibula) ; en dedans, le **semi-tendineux** (fin, saillant) et le **semi-membraneux** (plus large, plus profond). Remonter les corps musculaires jusqu’à la **tubérosité ischiatique**.","chk":"Les 3 tendons se tendent en flexion contrariée ; genou fléchi, la rotation externe fait saillir le biceps, la rotation interne les deux médiaux.","o":"**Tubérosité ischiatique** (long chef du biceps, semi-tendineux, semi-membraneux)","t":"Biceps : tête de la fibula · semi-tendineux : patte d’oie · semi-membraneux : condyle médial du tibia","nerf":"N. sciatique (L4–S3)","act":"**Extension de hanche + flexion du genou** (muscles bi-articulaires).","plates":[{"pl":"b-coupe-cuisse","num":13},{"pl":"b-fesse1","num":5}]},{"q":9,"name":"Piriforme","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Procubitus : profond, sur la ligne bord latéral du sacrum → sommet du grand trochanter. Le nerf sciatique sort juste dessous.","chk":"","o":"Face antérieure (pelvienne) du sacrum","t":"Bord supérieur du **grand trochanter**","nerf":"Plexus sacral (rameaux directs) (L4–S2) · n. du piriforme (S1–S2)","act":"**Rotation externe** hanche tendue ; abduction hanche fléchie ; coapte la tête fémorale.","old":["m-hanche-m5p","m-hanche-m5o","m-hanche-m5t","m-hanche-m5n","m-hanche-m5a"],"plates":[{"pl":"r-hanchemus","num":10},{"pl":"b-fesse2","num":2}]},{"q":10,"name":"Ilio-psoas","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Décubitus dorsal, hanche un peu fléchie : tendon profond sous le ligament inguinal, en dedans du sartorius, pendant une flexion contrariée. Palper doucement (paquet fémoral juste en dedans).","chk":"","o":"Psoas : corps et processus transverses de T12 à L5 · Iliaque : fosse iliaque","t":"**Petit trochanter** du fémur","nerf":"Plexus lombaire (rameaux directs) (L1–L3) · iliaque : n. fémoral","act":"**Fléchisseur principal** de la hanche (+ légère rotation externe) ; le psoas stabilise le rachis lombaire.","old":["m-hanche-m0p","m-hanche-m0o","m-hanche-m0t","m-hanche-m0n","m-hanche-m0a"],"plates":[{"pl":"r-hanchemus","num":1},{"pl":"b-cuisse-ant","num":6}]},{"q":11,"name":"Sartorius","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Décubitus dorsal, talon posé sur le genou opposé : corde oblique de l’EIAS vers le dedans du genou.","chk":"","o":"**EIAS**","t":"**Patte d’oie** (face médiale du tibia, sous le plateau)","nerf":"N. fémoral (L2–L4)","act":"Flexion + abduction + rotation externe de hanche, flexion du genou (« position du tailleur »).","old":["a-cuisse-m4p","a-cuisse-m4o","a-cuisse-m4t","a-cuisse-m4n","a-cuisse-m4a"],"plates":[{"pl":"r-hanchemus","num":3},{"pl":"b-coupe-cuisse","num":5},{"pl":"b-cuisse-ant","num":2}]},{"q":12,"name":"Droit fémoral","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Décubitus dorsal : corps fusiforme au milieu de la face antérieure de la cuisse ; tendon en V sous l’EIAS, entre sartorius et TFL, en flexion de hanche contrariée.","chk":"","o":"**EIAI** + sourcil de l’acétabulum","t":"Base de la patella → ligament patellaire → **tubérosité tibiale**","nerf":"N. fémoral (L2–L4)","act":"Extension du genou + **flexion de hanche** (bi-articulaire).","old":["a-cuisse-m0p","a-cuisse-m0o","a-cuisse-m0t","a-cuisse-m0n","a-cuisse-m0a"],"plates":[{"pl":"r-hanchemus","num":2},{"pl":"b-acetabulum","num":4},{"pl":"b-coupe-cuisse","num":1}]},{"q":13,"name":"Long adducteur","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Racine de la cuisse : le tendon le plus saillant près du pubis en adduction contrariée (bord médial du triangle fémoral).","chk":"","o":"Corps du pubis, sous le tubercule pubien","t":"Tiers moyen de la **ligne âpre**","nerf":"N. obturateur (L2–L4)","act":"**Adduction** de hanche (+ aide à la flexion).","old":["a-cuisse-m5p","a-cuisse-m5o","a-cuisse-m5t","a-cuisse-m5n","a-cuisse-m5a"],"plates":[{"pl":"r-hanchemus","num":6},{"pl":"b-coupe-cuisse","num":8},{"pl":"b-cuisse-ant","num":8}]},{"q":14,"name":"Gracile","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Tendon fin et rond en arrière du long adducteur, suivi jusqu’à la face médiale du genou.","chk":"","o":"Corps et branche inférieure du pubis","t":"**Patte d’oie**","nerf":"N. obturateur (L2–L4)","act":"Adduction de hanche + flexion et rotation interne du genou.","old":["a-cuisse-m8p","a-cuisse-m8o","a-cuisse-m8t","a-cuisse-m8n","a-cuisse-m8a"],"plates":[{"pl":"r-hanchemus","num":7},{"pl":"b-coupe-cuisse","num":10},{"pl":"b-cuisse-ant","num":9}]},{"q":15,"name":"Tenseur du fascia lata (TFL)","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Décubitus dorsal : juste sous et en arrière de l’EIAS, pendant une flexion + rotation interne contrariées.","chk":"","o":"**EIAS** et partie antérieure de la crête iliaque","t":"Tractus ilio-tibial → **tubercule de Gerdy** (tibia)","nerf":"N. glutéal supérieur (L4–S1)","act":"Flexion + abduction + rotation interne de hanche ; stabilise le genou en dehors.","old":["m-hanche-m4p","m-hanche-m4o","m-hanche-m4t","m-hanche-m4n","m-hanche-m4a"],"plates":[{"pl":"r-hanchemus","num":4},{"pl":"b-cuisse-ant","num":1}]},{"q":16,"name":"Patella","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"os","group":"Os","pos":"Décubitus dorsal, genou tendu et relâché","how":"Prendre la patella entre pouce et index, la mobiliser latéralement, palper base, pointe et bords.","chk":"Elle se bloque quand le quadriceps se contracte.","old":["a-parcours-x1-0"],"ins":"En haut, le **tendon du quadriceps** (droit fémoral + 3 vastes) ; en bas, le **ligament patellaire** ; sur les côtés, les rétinaculums.","plates":[{"pl":"r-parcours1","num":8},{"pl":"r-squelette","num":6},{"pl":"b-cuisse-ant","num":10}]},{"q":17,"name":"Tubérosité tibiale","reg":"jambe","regName":"Jambe","kind":"os","group":"Os","pos":"Assis, genou fléchi à 90°.","how":"Partir de la pointe de la patella et descendre le long du ligament patellaire jusqu’à la **saillie osseuse antérieure** du tibia.","chk":"C’est l’arrivée du **ligament patellaire** (appareil extenseur du quadriceps) ; elle est à peu près à hauteur de la tête de la fibula.","ins":"Le **ligament patellaire** : terminaison de tout l'appareil extenseur du **quadriceps**.","plates":[{"pl":"r-parcours1","num":9},{"pl":"r-squelette","num":7},{"pl":"b-tibia","num":4}]},{"q":18,"name":"Tête de la fibula","reg":"jambe","regName":"Jambe","kind":"os","group":"Os","pos":"Assis, genou fléchi","how":"Face latérale du genou, en arrière, à peu près au niveau de la tubérosité tibiale ; suivre le tendon du biceps.","chk":"On peut la mobiliser d’avant en arrière. Ne pas appuyer sur le col : nerf fibulaire commun.","old":["a-parcours-x1-4"],"ins":"**Biceps fémoral** ; **ligament collatéral fibulaire** du genou ; origine du **long fibulaire** et d'une partie du **soléaire**.","plates":[{"pl":"r-parcours1","num":12},{"pl":"r-squelette","num":11},{"pl":"b-genou","num":5}]},{"q":19,"name":"Tubercule infracondylaire du tibia (tubercule de Gerdy)","reg":"jambe","regName":"Jambe","kind":"os","group":"Os","pos":"Assis, genou fléchi","how":"Face antéro-latérale du tibia, en dehors de la tubérosité tibiale.","chk":"Le tractus ilio-tibial s’y termine (on le sent se tendre jambe tendue en rotation interne).","old":["a-parcours-x1-6"],"ins":"Le **tractus ilio-tibial** (fascia lata tendu par le **TFL** et le **grand fessier**) ; quelques fibres du **tibial antérieur**.","plates":[{"pl":"r-parcours1","num":13}]},{"q":20,"name":"Biceps fémoral","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Procubitus, flexion contrariée : gros tendon au bord latéral du creux poplité, jusqu’à la tête de la fibula.","chk":"","o":"Long chef : **tubérosité ischiatique** · Court chef : ligne âpre","t":"**Tête de la fibula**","nerf":"N. sciatique (contingent tibial) (L4–S3) · court chef : n. fibulaire commun","act":"Extension de hanche + flexion du genou + **rotation externe** du genou fléchi.","old":["a-cuisse-m11p","a-cuisse-m11o","a-cuisse-m11t","a-cuisse-m11n","a-cuisse-m11a"],"plates":[{"pl":"r-hanchemus","num":14},{"pl":"b-cuisse-post","num":3},{"pl":"b-jambe-ext","num":10}]},{"q":21,"name":"Semi-tendineux","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Procubitus, flexion du genou contrariée : tendon fin et très saillant au bord médial du creux poplité.","chk":"","o":"**Tubérosité ischiatique** (tendon commun avec le biceps)","t":"**Patte d’oie**","nerf":"N. sciatique (contingent tibial) (L4–S3)","act":"Extension de hanche + **flexion du genou** + rotation interne du genou fléchi.","old":["a-cuisse-m9p","a-cuisse-m9o","a-cuisse-m9t","a-cuisse-m9n","a-cuisse-m9a"],"plates":[{"pl":"r-hanchemus","num":15},{"pl":"b-cuisse-int","num":6},{"pl":"b-cuisse-post","num":4}]},{"q":22,"name":"Semi-membraneux","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"De part et d’autre du tendon du semi-tendineux, plus large et plus profond, au bord médial du creux poplité.","chk":"","o":"**Tubérosité ischiatique**","t":"Face postéro-médiale du condyle médial du tibia","nerf":"N. sciatique (contingent tibial) (L4–S3)","act":"Extension de hanche + flexion du genou + rotation interne.","old":["a-cuisse-m10p","a-cuisse-m10o","a-cuisse-m10t","a-cuisse-m10n","a-cuisse-m10a"],"plates":[{"pl":"r-hanchemus","num":16},{"pl":"b-cuisse-int","num":6},{"pl":"b-cuisse-post","num":5}]},{"q":23,"name":"Gastrocnémien","reg":"jambe","regName":"Jambe","kind":"muscle","group":"Muscles","pos":"","how":"Debout sur la pointe des pieds : les 2 renflements du mollet (le médial descend plus bas), bords inférieurs en « V ».","chk":"","o":"Chef médial : au-dessus du condyle médial du fémur · Chef latéral : au-dessus du condyle latéral","t":"**Tendon calcanéen** → tubérosité du calcanéus","nerf":"N. tibial (L4–S3)","act":"**Flexion plantaire** (propulsion, saut) + flexion du genou (bi-articulaires).","old":["a-jambe-m6p","a-jambe-m6o","a-jambe-m6t","a-jambe-m6n","a-jambe-m6a"],"plates":[{"pl":"b-coupe-jambe","num":11},{"pl":"b-cuisse-post","num":8},{"pl":"b-jambe-ant","num":7}]},{"q":24,"name":"Ligament patellaire","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"tendon","group":"Muscles","pos":"Assis genou fléchi à 90°, ou décubitus dorsal genou tendu.","how":"La **corde** tendue entre la **pointe de la patella** et la **tubérosité tibiale** : la pincer entre pouce et index.","chk":"Elle se tend quand le patient contracte le quadriceps (extension du genou) et devient souple quand il se relâche.","plates":[{"pl":"r-parcours1","num":9},{"pl":"b-cuisse-ant","num":11},{"pl":"b-genou","num":2}]},{"q":25,"name":"Vaste médial","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Genou tendu, serrer la cuisse : relief en « goutte d’eau » au-dessus et en dedans de la patella.","chk":"","o":"Lèvre médiale de la ligne âpre du fémur","t":"Bord médial de la patella + tendon quadricipital","nerf":"N. fémoral (L2–L4)","act":"Extension du genou ; ses fibres basses stabilisent la patella en dedans.","old":["a-cuisse-m1p","a-cuisse-m1o","a-cuisse-m1t","a-cuisse-m1n","a-cuisse-m1a"],"plates":[{"pl":"b-coupe-cuisse","num":2},{"pl":"b-cuisse-ant","num":5},{"pl":"b-cuisse-int","num":1}]},{"q":26,"name":"Vaste latéral","reg":"cuisse","regName":"Cuisse, hanche & bassin","kind":"muscle","group":"Muscles","pos":"","how":"Face latérale de la cuisse, sous le tractus ilio-tibial, pendant une extension du genou contrariée.","chk":"","o":"Grand trochanter + lèvre latérale de la ligne âpre","t":"Bord latéral de la patella + tendon quadricipital","nerf":"N. fémoral (L2–L4)","act":"Extension du genou.","old":["a-cuisse-m2p","a-cuisse-m2o","a-cuisse-m2t","a-cuisse-m2n","a-cuisse-m2a"],"plates":[{"pl":"b-coupe-cuisse","num":3},{"pl":"b-cuisse-ant","num":4},{"pl":"b-fesse1","num":4}]},{"q":27,"name":"Patte d’oie","reg":"jambe","regName":"Jambe","kind":"tendon","group":"Muscles","pos":"Décubitus dorsal ou assis","how":"Face médiale du tibia, 3 doigts sous l’interligne : sartorius, gracile, semi-tendineux.","chk":"Les tendons saillent en flexion du genou contrariée.","old":["a-parcours-x1-7"],"plates":[{"pl":"r-parcours1","num":14},{"pl":"b-cuisse-int","num":4}]},{"q":28,"name":"Sinus du tarse","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Assis","how":"Creux en avant de la malléole latérale ; relever les orteils.","chk":"Le muscle pédieux forme une petite masse molle qui durcit.","old":["a-parcours-x4-5"],"ins":"En avant, l'origine du **court extenseur des orteils** ; dedans, les ligaments **talo-calcanéen interosseux** et **cervical** ; le rétinaculum des extenseurs.","plates":[{"pl":"r-parcours2","num":18}]},{"q":29,"name":"Trochlée du talus","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Assis ou décubitus dorsal, pied relâché.","how":"En avant de la mortaise, **entre les deux malléoles**, sous les tendons extenseurs : mettre le pied en **flexion plantaire** passive, la poulie du talus vient se découvrir en avant du tibia.","chk":"Elle se cache sous le tibia en flexion dorsale et réapparaît en flexion plantaire.","ins":"**Aucun muscle** ne s'insère sur le talus ! Seulement des ligaments (talo-fibulaires, deltoïdien) ; les tendons des extenseurs passent devant.","plates":[{"pl":"r-squelette","num":14},{"pl":"r-voute","num":1},{"pl":"b-cheville","num":8}]},{"q":30,"name":"Col du talus","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Assis, pied en légère flexion plantaire.","how":"En avant de la trochlée : petite **dépression** entre la trochlée (en arrière) et la **tête du talus** (en avant). En dehors, il surplombe le **sinus du tarse**.","chk":"En faisant tourner le pied en dedans et en dehors, la tête du talus bouge juste en avant du col.","ins":"**Aucun muscle** (le talus n'a pas d'insertion musculaire) ; la capsule talo-crurale et le ligament talo-naviculaire.","plates":[{"pl":"r-squelette","num":14},{"pl":"r-voute","num":1},{"pl":"b-cheville","num":8}]},{"q":31,"name":"Articulation métatarso-phalangienne de l’hallux","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Décubitus dorsal ou assis, pied relâché.","how":"Suivre le bord médial du **1er métatarsien** jusqu’à sa tête : l’**interligne** est juste en avant, à la base de la phalange proximale de l’hallux.","chk":"Mobiliser l’hallux en flexion et en extension : l’interligne s’ouvre sous le doigt. Les **sésamoïdes** roulent dessous.","ins":"Base de P1 : **abducteur** et **adducteur de l'hallux**, **court extenseur de l'hallux** ; dessous, le **court fléchisseur** (par les sésamoïdes) ; les tendons des **longs extenseur et fléchisseur** passent vers P2.","plates":[{"pl":"r-parcours2","num":12}]},{"q":32,"name":"1er métatarsien","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Assis ou décubitus dorsal.","how":"Bord médial du pied : de la **base** (en avant du cunéiforme médial, arrivée du tibial antérieur) à la **tête**, en suivant la diaphyse sur sa face dorsale et médiale.","chk":"En mobilisant la tête, on sent l’interligne cunéo-métatarsien bouger à la base.","ins":"Base : **long fibulaire** (en dessous, en dehors) et **tibial antérieur** (en dedans) ; origine du **1er interosseux dorsal**.","plates":[{"pl":"r-voute","num":6},{"pl":"b-pied-os","num":7}]},{"q":33,"name":"Cunéiforme médial","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Assis.","how":"En avant du **naviculaire**, sur le bord médial : suivre le tendon du **tibial antérieur** jusqu’à son arrivée.","chk":"En mobilisant le 1er métatarsien, l’interligne cunéo-métatarsien bouge juste en avant de lui.","ins":"**Tibial antérieur** (face médiale) et **long fibulaire** (face plantaire) ; des expansions du **tibial postérieur**.","plates":[{"pl":"r-parcours2","num":11},{"pl":"r-voute","num":5}]},{"q":34,"name":"Tubérosité de l’os naviculaire","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Assis","how":"Saillie la plus médiale du bord médial, 2–3 cm en avant et sous la malléole médiale.","chk":"Le tendon du tibial postérieur y arrive (inversion contrariée).","old":["a-parcours-x3-2"],"ins":"Le **tibial postérieur** (sa terminaison principale) ; le ligament calcanéo-naviculaire plantaire (spring ligament).","plates":[{"pl":"r-parcours2","num":10},{"pl":"r-voute","num":4},{"pl":"b-pied-os","num":3}]},{"q":35,"name":"Malléole tibiale (médiale)","reg":"jambe","regName":"Jambe","kind":"os","group":"Os","pos":"Assis, pied pendant","how":"Extrémité inférieure du tibia, face médiale.","chk":"Plus haute et plus en avant que la malléole latérale.","old":["a-parcours-x2-1"],"ins":"Le **ligament deltoïdien** (collatéral médial) ; derrière elle passent le **tibial postérieur** et le **long fléchisseur des orteils**.","plates":[{"pl":"r-parcours2","num":2},{"pl":"r-squelette","num":9},{"pl":"r-voute","num":8}]},{"q":36,"name":"Sustentaculum tali","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Assis","how":"Un travers de doigt sous la malléole médiale.","chk":"Petite saillie du calcanéus ; le long fléchisseur de l’hallux glisse dessous.","old":["a-parcours-x3-1"],"ins":"Dessous passe le **long fléchisseur de l'hallux** ; s'y attachent le **ligament calcanéo-naviculaire plantaire** et le faisceau tibio-calcanéen du deltoïdien.","plates":[{"pl":"r-parcours2","num":9},{"pl":"r-voute","num":3}]},{"q":37,"name":"Cuboïde","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Assis","how":"Juste en arrière de la base du M5, sur le bord latéral.","chk":"Le long fibulaire passe dans sa gouttière, en dessous.","old":["a-parcours-x4-2"],"ins":"Le **long fibulaire** passe dans sa gouttière plantaire ; expansions du **tibial postérieur** ; ligaments plantaires (long ligament plantaire).","plates":[{"pl":"r-parcours2","num":15},{"pl":"r-squelette","num":15},{"pl":"r-voute","num":10}]},{"q":38,"name":"Trochlée fibulaire (tubercule des fibulaires)","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Assis","how":"Sous la malléole latérale, sur la face latérale du calcanéus.","chk":"Entre les 2 tendons fibulaires en éversion contrariée.","old":["a-parcours-x4-0"],"ins":"Elle sépare le **court fibulaire** (au-dessus) du **long fibulaire** (en dessous) ; le rétinaculum inférieur des fibulaires s'y fixe.","plates":[{"pl":"r-parcours2","num":13}]},{"q":39,"name":"Malléole fibulaire (latérale)","reg":"jambe","regName":"Jambe","kind":"os","group":"Os","pos":"Assis, pied pendant","how":"Extrémité inférieure de la fibula.","chk":"Plus basse (≈ 1 cm) et plus en arrière que la médiale.","old":["a-parcours-x2-2"],"ins":"Le **ligament collatéral latéral** (talo-fibulaire antérieur, calcanéo-fibulaire, talo-fibulaire postérieur) ; derrière passent le **long** et le **court fibulaire**.","plates":[{"pl":"r-parcours2","num":3},{"pl":"r-squelette","num":12},{"pl":"r-voute","num":9}]},{"q":40,"name":"Processus médial de la tubérosité du calcanéus","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Procubitus, pieds dépassant de la table (ou décubitus dorsal, pied relâché).","how":"Face **plantaire du talon**, côté **médial** : appuyer fermement du pouce sous la tubérosité du calcanéus, en avant de l’arrière du talon.","chk":"C’est l’origine de l’**abducteur de l’hallux**, du **court fléchisseur des orteils** et de l’**aponévrose plantaire**.","ins":"Origine de l'**abducteur de l'hallux**, du **court fléchisseur des orteils** et de l'**aponévrose plantaire** (le tendon calcanéen est juste au-dessus, en arrière).","plates":[{"pl":"r-squelette","num":13},{"pl":"r-voute","num":2},{"pl":"b-apo-plantaire","num":1}]},{"q":41,"name":"Sésamoïdes","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Décubitus dorsal","how":"Face plantaire de la tête du M1 ; mobiliser l’hallux en flexion/extension.","chk":"Les sésamoïdes roulent sous le pouce.","old":["a-parcours-x3-4"],"ins":"Les deux chefs du **court fléchisseur de l'hallux** ; l'**abducteur** (médial) et l'**adducteur de l'hallux** (latéral) ; le **long fléchisseur de l'hallux** passe entre eux.","plates":[{"pl":"r-parcours2","num":12}]},{"q":42,"name":"Tibial antérieur","reg":"jambe","regName":"Jambe","kind":"muscle","group":"Muscles","pos":"","how":"Assis, pied relevé et tourné en dedans contre résistance : le **tendon le plus médial et le plus gros** devant la cheville ; corps charnu le long de la crête tibiale.","chk":"","o":"Condyle latéral et 2/3 supérieurs de la face latérale du tibia, membrane interosseuse","t":"Face médiale du **cunéiforme médial** + base du **M1**","nerf":"N. fibulaire profond (L4–S1)","act":"**Flexion dorsale + inversion** ; freine la retombée du pied après l’attaque du talon.","old":["a-jambe-m0p","a-jambe-m0o","a-jambe-m0t","a-jambe-m0n","a-jambe-m0a"],"plates":[{"pl":"b-coupe-jambe","num":3},{"pl":"b-cuisse-ant","num":13},{"pl":"b-jambe-ant","num":1}]},{"q":43,"name":"Long extenseur de l’hallux","reg":"jambe","regName":"Jambe","kind":"muscle","group":"Muscles","pos":"","how":"Relever le gros orteil contre résistance : tendon en dehors du tibial antérieur. Le pouls pédieux est juste en dehors.","chk":"","o":"Face médiale de la fibula (tiers moyen) + membrane interosseuse","t":"Base de la **phalange distale de l’hallux**","nerf":"N. fibulaire profond (L4–S1)","act":"Extension de l’hallux + flexion dorsale.","old":["a-jambe-m1p","a-jambe-m1o","a-jambe-m1t","a-jambe-m1n","a-jambe-m1a"],"plates":[{"pl":"b-jambe-ant","num":8},{"pl":"b-pied-dos","num":2}]},{"q":44,"name":"Long extenseur des orteils","reg":"jambe","regName":"Jambe","kind":"muscle","group":"Muscles","pos":"","how":"Relever les orteils : 4 tendons en éventail sur le dos du pied, en dehors du long extenseur de l’hallux.","chk":"","o":"Condyle latéral du tibia, face médiale de la fibula, membrane interosseuse","t":"Phalanges moyennes et distales des **orteils 2 à 5**","nerf":"N. fibulaire profond (L4–S1)","act":"Extension des orteils 2–5 + flexion dorsale + éversion.","old":["a-jambe-m2p","a-jambe-m2o","a-jambe-m2t","a-jambe-m2n","a-jambe-m2a"],"plates":[{"pl":"b-coupe-jambe","num":4},{"pl":"b-jambe-ant","num":2},{"pl":"b-jambe-ext","num":2}]},{"q":45,"name":"Court extenseur de l’hallux","reg":"pied","regName":"Pied","kind":"muscle","group":"Muscles","pos":"Assis, pied relâché.","how":"Sur le dos du pied, en dehors du tendon du long extenseur de l’hallux : c’est le **chef médial du pédieux**, qui file vers la phalange proximale de l’hallux.","chk":"Il se contracte en extension contrariée du gros orteil.","o":"Face dorsale du **calcanéus** (sinus du tarse), avec le court extenseur des orteils","t":"Base de la **phalange proximale de l’hallux**","nerf":"N. fibulaire profond (L4–S1)","act":"Extension de l’hallux (MTP).","plates":[{"pl":"b-jambe-ext","num":8},{"pl":"b-pied-dos","num":4}]},{"q":46,"name":"Court extenseur des orteils","reg":"pied","regName":"Pied","kind":"muscle","group":"Muscles","pos":"","how":"Relever les orteils : petite masse molle en avant de la malléole latérale (sinus du tarse) ; à ne pas confondre avec un œdème.","chk":"","o":"Face dorsale du calcanéus (sinus du tarse)","t":"Tendons extenseurs des orteils 2 à 4","nerf":"N. fibulaire profond (L4–S1)","act":"Extension des orteils 2 à 4.","old":["m-pied-m0p","m-pied-m0o","m-pied-m0t","m-pied-m0n","m-pied-m0a"],"plates":[{"pl":"b-jambe-ext","num":8},{"pl":"b-pied-dos","num":4}]},{"q":47,"name":"Tibial postérieur","reg":"jambe","regName":"Jambe","kind":"muscle","group":"Muscles","pos":"","how":"Inversion contrariée : juste **derrière la malléole médiale** (le plus antérieur), jusqu’au tubercule du naviculaire.","chk":"","o":"Membrane interosseuse + faces postérieures du tibia et de la fibula","t":"**Tubérosité du naviculaire** (+ cunéiformes, cuboïde, bases M2–M4)","nerf":"N. tibial (L4–S3)","act":"**Inversion** + flexion plantaire ; **soutient l’arche médiale**.","old":["a-jambe-m8p","a-jambe-m8o","a-jambe-m8t","a-jambe-m8n","a-jambe-m8a"],"plates":[{"pl":"r-parcours2","num":6},{"pl":"r-vaisseaux","num":8},{"pl":"b-coupe-jambe","num":7}]},{"q":48,"name":"Soléaire","reg":"jambe","regName":"Jambe","kind":"muscle","group":"Muscles","pos":"","how":"Genou fléchi (à genoux sur une chaise), flexion plantaire : relief de part et d’autre du tendon, sous les gastrocnémiens.","chk":"","o":"Tête et face postérieure de la fibula + ligne du soléaire du tibia","t":"**Tendon calcanéen** → tubérosité du calcanéus","nerf":"N. tibial (L4–S3)","act":"**Flexion plantaire** (efficace genou fléchi) ; muscle postural ; **pompe veineuse** du mollet.","old":["a-jambe-m7p","a-jambe-m7o","a-jambe-m7t","a-jambe-m7n","a-jambe-m7a"],"plates":[{"pl":"b-coupe-jambe","num":10},{"pl":"b-jambe-ant","num":7},{"pl":"b-jambe-ext","num":5}]},{"q":49,"name":"Tendon calcanéen","reg":"jambe","regName":"Jambe","kind":"tendon","group":"Muscles","pos":"Procubitus, pieds dépassant de la table","how":"Pincer la corde entre pouce et index, du mollet jusqu’au talon.","chk":"Il se tend en flexion plantaire ; réflexe achilléen (S1).","old":["a-parcours-x2-3"],"plates":[{"pl":"r-parcours2","num":4},{"pl":"b-jambe-ext","num":7},{"pl":"b-jambe-post","num":3}]},{"q":50,"name":"Long fibulaire","reg":"jambe","regName":"Jambe","kind":"muscle","group":"Muscles","pos":"","how":"Éversion contrariée : derrière la malléole latérale (le plus postérieur des deux tendons), puis sous le tubercule des fibulaires ; corps charnu sous la tête de la fibula.","chk":"","o":"Tête et 2/3 supérieurs de la face latérale de la fibula","t":"**Base du M1 + cunéiforme médial** (face plantaire), après être passé derrière la malléole latérale et sous le cuboïde","nerf":"N. fibulaire superficiel (L5–S1)","act":"**Éversion** + flexion plantaire ; abaisse le M1, soutient l’arche transversale.","old":["a-jambe-m4p","a-jambe-m4o","a-jambe-m4t","a-jambe-m4n","a-jambe-m4a"],"plates":[{"pl":"b-jambe-ant","num":3},{"pl":"b-jambe-ext","num":3},{"pl":"b-pied-lig","num":8}]},{"q":51,"name":"Court fibulaire","reg":"jambe","regName":"Jambe","kind":"muscle","group":"Muscles","pos":"","how":"Éversion contrariée : tendon de la malléole latérale (au-dessus du tubercule des fibulaires) jusqu’à la base du M5.","chk":"","o":"2/3 inférieurs de la face latérale de la fibula","t":"**Tubérosité de la base du M5**","nerf":"N. fibulaire superficiel (L5–S1)","act":"**Éversion** (abducteur principal du pied) + flexion plantaire.","old":["a-jambe-m5p","a-jambe-m5o","a-jambe-m5t","a-jambe-m5n","a-jambe-m5a"],"plates":[{"pl":"b-coupe-jambe","num":6},{"pl":"b-jambe-ext","num":4},{"pl":"b-jambe-post","num":4}]},{"q":52,"name":"Long fléchisseur des orteils","reg":"jambe","regName":"Jambe","kind":"muscle","group":"Muscles","pos":"","how":"Flexion des orteils contrariée : derrière le tendon du tibial postérieur, en arrière de la malléole médiale.","chk":"","o":"Face postérieure du tibia","t":"Bases des **phalanges distales des orteils 2 à 5**","nerf":"N. tibial (L4–S3)","act":"Flexion des orteils 2–5 + flexion plantaire + inversion.","old":["a-jambe-m9p","a-jambe-m9o","a-jambe-m9t","a-jambe-m9n","a-jambe-m9a"],"plates":[{"pl":"b-pied-plante","num":8},{"pl":"b-plante-prof","num":5}]},{"q":53,"name":"Long fléchisseur de l’hallux","reg":"jambe","regName":"Jambe","kind":"muscle","group":"Muscles","pos":"","how":"Le plus postérieur, entre la malléole médiale et le tendon calcanéen, en flexion du gros orteil contrariée ; aussi sous le sustentaculum tali.","chk":"","o":"Face postérieure de la fibula (2/3 inférieurs)","t":"Base de la **phalange distale de l’hallux** (passe sous le sustentaculum tali)","nerf":"N. tibial (L4–S3)","act":"Flexion de l’hallux ; **propulsion** du pas ; soutien de l’arche médiale.","old":["a-jambe-m10p","a-jambe-m10o","a-jambe-m10t","a-jambe-m10n","a-jambe-m10a"],"plates":[{"pl":"b-pied-plante","num":9}]},{"q":54,"name":"Court fléchisseur des orteils","reg":"pied","regName":"Pied","kind":"muscle","group":"Muscles","pos":"","how":"Milieu de la plante, sous l’aponévrose, en fléchissant les orteils.","chk":"","o":"Tubérosité du calcanéus + aponévrose plantaire","t":"Phalanges moyennes des orteils 2 à 5","nerf":"N. plantaire médial (L4–L5)","act":"Flexion des orteils 2–5 ; soutient la voûte.","old":["m-pied-m2p","m-pied-m2o","m-pied-m2t","m-pied-m2n","m-pied-m2a"],"plates":[{"pl":"b-pied-plante","num":1}]},{"q":55,"name":"Court fléchisseur de l’hallux","reg":"pied","regName":"Pied","kind":"muscle","group":"Muscles","pos":"","how":"Sous la tête du M1 : sésamoïdes mobiles quand on fléchit et étend le gros orteil.","chk":"","o":"Cuboïde et cunéiforme latéral (face plantaire)","t":"Base de la phalange proximale de l’hallux, par les **2 sésamoïdes**","nerf":"N. plantaire médial (L4–L5)","act":"Flexion de la MTP1 ; appui de l’avant-pied médial.","old":["m-pied-m3p","m-pied-m3o","m-pied-m3t","m-pied-m3n","m-pied-m3a"],"plates":[{"pl":"b-plante-prof","num":6}]},{"q":56,"name":"Abducteur du 5e orteil","reg":"pied","regName":"Pied","kind":"muscle","group":"Muscles","pos":"","how":"Bord latéral de la plante, du talon à la base du M5.","chk":"","o":"Processus latéral de la tubérosité du calcanéus","t":"Base de la phalange proximale du 5e orteil","nerf":"N. plantaire latéral (S1–S2)","act":"Abduction et flexion du 5e orteil ; soutien du bord latéral.","old":["m-pied-m4p","m-pied-m4o","m-pied-m4t","m-pied-m4n","m-pied-m4a"],"plates":[{"pl":"b-plante-prof","num":4}]},{"q":57,"name":"Court fléchisseur du 5e orteil","reg":"pied","regName":"Pied","kind":"muscle","group":"Muscles","pos":"Décubitus dorsal ou procubitus, pied relâché.","how":"Bord latéral de la plante, **sous la diaphyse du 5e métatarsien**, en dedans de l’abducteur du 5e orteil.","chk":"Il se contracte en **flexion contrariée** du 5e orteil (MTP).","o":"Base du **5e métatarsien** (et gaine du long fibulaire)","t":"Base de la **phalange proximale du 5e orteil**","nerf":"N. plantaire latéral (S1–S2)","act":"Flexion de la MTP du 5e orteil.","plates":[{"pl":"b-plante-prof","num":9}]},{"q":58,"name":"Abducteur de l’hallux","reg":"pied","regName":"Pied","kind":"muscle","group":"Muscles","pos":"","how":"Bord médial de la plante, entre le talon et la tête du M1, en écartant le gros orteil.","chk":"","o":"Processus médial de la **tubérosité du calcanéus**","t":"Base de la phalange proximale de l’hallux (côté médial)","nerf":"N. plantaire médial (L4–L5)","act":"Abduction de l’hallux ; soutient l’arche médiale.","old":["m-pied-m1p","m-pied-m1o","m-pied-m1t","m-pied-m1n","m-pied-m1a"],"plates":[{"pl":"b-apo-plantaire","num":6},{"pl":"b-pied-plante","num":2},{"pl":"b-plante-prof","num":2}]},{"q":59,"name":"2e métatarsien","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Assis ou décubitus dorsal.","how":"Sur le dos du pied, le **plus long** des métatarsiens : sa base est encastrée en retrait, dans la **mortaise des cunéiformes** ; suivre la diaphyse jusqu’à la tête, palpable aussi sous l’avant-pied.","chk":"Base presque immobile (clé de voûte de l’interligne de Lisfranc) ; en mobilisant le 2e orteil, on sent l’interligne métatarso-phalangien.","ins":"Origine des **1er et 2e interosseux dorsaux** ; le chef oblique de l'**adducteur de l'hallux** ; expansions du **tibial postérieur** à la base.","plates":[{"pl":"r-parcours2","num":20}]},{"q":60,"name":"5e métatarsien","reg":"pied","regName":"Pied","kind":"os","group":"Os","pos":"Assis","how":"Saillie au milieu du bord latéral du pied.","chk":"Le tendon du court fibulaire s’y termine.","old":["a-parcours-x4-1"],"ins":"Base (styloïde) : **court fibulaire** ; face dorsale : **3e fibulaire** ; origine du **court fléchisseur** et de l'**opposant du 5e** ; l'**abducteur du 5e** ; interosseux.","plates":[{"pl":"r-squelette","num":16},{"pl":"r-voute","num":11},{"pl":"b-pied-os","num":6}]}];
